from pathlib import Path
import json,hashlib,shutil,base64,html,zipfile
R=Path.cwd();D=R/'build/dialogue-extracts';M=D/'sampler-media';(M/'wav').mkdir(parents=True,exist_ok=True);(M/'mp3').mkdir(exist_ok=True)
folders=['X1PiR7WfuWs','grande-vadrouille','folie-des-grandeurs','oscar','oscar-vole','oscar-amant','rabbi-jacob','grand-restaurant','vadrouille-tea-for-two','vadrouille-prisonnier'];rows=[]
for folder in folders:
 p=D/folder;manifest=p/'dialogues.json'
 if manifest.exists():clips=json.loads(manifest.read_text(encoding='utf8'))
 else:clips=[json.loads((p/'dialogue.json').read_text(encoding='utf8'))]
 for r in clips:
  if folder=='X1PiR7WfuWs' and r.get('id','').startswith(('03-','04-')):continue
  stem=Path(r['mp3File']).stem;id=folder+'--'+stem;n=len(rows)+1
  record=dict(r);record.update(id=id,number=n,extractionFolder=folder,originalId=r.get('id',stem))
  for key,kind,hashkey in [('wavFile','wav','sha256'),('mp3File','mp3','mp3Sha256')]:
   src=p/r[key];assert hashlib.sha256(src.read_bytes()).hexdigest()==r[hashkey]
   name=f'{n:02d}-{folder}-{stem}.{kind}';dest=M/kind/name;shutil.copyfile(src,dest);record[key]='sampler-media/'+kind+'/'+name
  rows.append(record)
review_path=D/'sampler-review.json'
review=json.loads(review_path.read_text(encoding='utf-8-sig')) if review_path.exists() else {}
for record in rows:
 if record['id'] in review:
  record['reviewStatus']='approved_by_user' if review[record['id']] else 'rejected_by_user'
assert len(rows)==21
films=list(dict.fromkeys(r['film'] for r in rows));assert len(films)==6
(D/'sampler-manifest.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
css='''*{box-sizing:border-box}body{margin:0;background:#0e1623;color:#edf4ff;font:18px/1.5 system-ui}main{max-width:1180px;margin:auto;padding:32px 22px}h1{font-size:clamp(30px,5vw,43px);line-height:1.15;margin:8px 0 16px}.eyebrow{color:#efc477;letter-spacing:.14em;text-transform:uppercase;font-size:13px}.intro,.meta{color:#bac9dc}.toolbar{background:#0e1623;padding:12px 0;display:flex;flex-wrap:wrap;align-items:center;gap:10px;position:sticky;top:0;z-index:2;border-bottom:1px solid #364359}button,select,input[type=search]{font:inherit;border-radius:9px;border:1px solid #526681;padding:10px 14px;background:#233550;color:#eef4ff;max-width:100%}button{cursor:pointer}button:hover,button:focus-visible{outline:2px solid #e4ba70;outline-offset:2px}.primary{background:#e9bd69;color:#19202b;font-weight:700;border-color:#e9bd69}a{color:#a2d7ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:18px;margin:18px 0}article{background:#1a2940;border:1px solid #3b4d68;border-radius:14px;padding:20px;min-width:0}article.playing{border-color:#f0c26b;box-shadow:0 0 0 2px #906b34}article[hidden]{display:none}h2{font-size:22px;line-height:1.42;margin:12px 0 16px}.film{color:#e8bf78;font-size:16px}.meta{font-size:14px}audio{width:100%;margin:6px 0 10px}label.keep{display:flex;gap:10px;align-items:center;margin:16px 0 8px;font-weight:600}input[type=checkbox]{width:20px;height:20px;accent-color:#efc477}.downloads{font-size:16px}details{font-size:14px;margin-top:14px;overflow-wrap:anywhere}summary{cursor:pointer}#status{min-height:28px;margin:15px 0;color:#e6d1aa}footer{font-size:15px;color:#bac9dc;margin:30px 0}'''
page='<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Répliques de cinéma — sampler complet</title><style>'+css+'</style><main><div class="eyebrow">TriviaParty · répliques de cinéma</div><h1>Tous les nouveaux extraits</h1><p class="intro">21 extraits de 6 films, réunis pour une écoute continue. Les deux passages rejetés de La Chèvre sont exclus. Les fichiers sont conservés à l’identique.</p><p><a href="./Repliques-cinema-21-extraits.zip">Télécharger tous les WAV et MP3</a></p><section class="toolbar" aria-label="Filtres et lecture"><select id="film" aria-label="Film"><option value="">Tous les films</option>'+''.join('<option>'+html.escape(f)+'</option>' for f in films)+'</select><input id="search" type="search" placeholder="Rechercher une réplique" aria-label="Rechercher une réplique"><select id="kept" aria-label="Filtrer les favoris"><option value="all">Tous les extraits</option><option value="yes">À garder</option><option value="no">À écarter</option></select><button id="all" class="primary">Tout écouter</button><button id="stop">Arrêter</button><button id="export">Exporter mes choix</button></section><p class="meta" id="count"></p><p id="status" role="status" aria-live="polite">Choisissez un extrait ou lancez l’écoute enchaînée.</p><section class="grid">'
for r in rows:
 payload=base64.b64encode((D/r['mp3File']).read_bytes()).decode();page+=f'<article data-id="{html.escape(r["id"],quote=True)}" data-film="{html.escape(r["film"],quote=True)}"><div class="film">{r["number"]:02d} · {html.escape(r["film"])}</div><h2>{html.escape(r["text"])}</h2><p class="meta">{r["durationSeconds"]} s</p><audio controls preload="none" src="data:audio/mpeg;base64,{payload}"></audio><div class="downloads"><a download href="./{html.escape(r["wavFile"],quote=True)}">WAV</a> · <a download href="./{html.escape(r["mp3File"],quote=True)}">MP3</a></div><label class="keep"><input type="checkbox" checked> À garder</label><details><summary>Source et découpe</summary><p><a href="{html.escape(r["sourceUrl"],quote=True)}" target="_blank" rel="noopener">Ouvrir la source</a> · {r["startSeconds"]:.2f}–{r["endSeconds"]:.2f} s</p></details></article>'
page+='</section><footer>L’écoute enchaînée suit les filtres. Vos choix restent sur cet appareil ; « Exporter mes choix » crée un fichier à conserver. Les extraits sont inclus dans cette page et se lisent sans connexion. La banque du jeu n’a pas été modifiée.</footer></main><script>const tracks='+json.dumps([dict(id=r['id'],number=r['number'],film=r['film'],text=r['text'],durationSeconds=r['durationSeconds'],keep=r.get('reviewStatus')!='rejected_by_user') for r in rows],ensure_ascii=False).replace('<','\\u003c')+';'
page+='''const cards=[...document.querySelectorAll('article')],audios=cards.map(c=>c.querySelector('audio')),status=document.querySelector('#status'),count=document.querySelector('#count');let queue=[],active=null,automatic=false,saved={};try{saved=JSON.parse(localStorage.getItem('triviaparty-dialogue-sampler-choices')||'{}')}catch(e){}function remember(){saved={};cards.forEach(c=>saved[c.dataset.id]=c.querySelector('input').checked);try{localStorage.setItem('triviaparty-dialogue-sampler-choices',JSON.stringify(saved))}catch(e){}}function filter(){const f=document.querySelector('#film').value,q=document.querySelector('#search').value.trim().toLocaleLowerCase(),k=document.querySelector('#kept').value;let visible=0;cards.forEach(c=>{const yes=c.querySelector('input').checked;c.hidden=!!((f&&c.dataset.film!==f)||(q&&!c.querySelector('h2').textContent.toLocaleLowerCase().includes(q))||(k==='yes'&&!yes)||(k==='no'&&yes));if(!c.hidden)visible++});count.textContent=visible+' / '+cards.length+' extraits affichés · '+cards.filter(c=>c.querySelector('input').checked).length+' à garder'}function stop(){queue=[];automatic=false;audios.forEach(a=>{a.pause();a.currentTime=0});cards.forEach(c=>c.classList.remove('playing'));active=null;status.textContent='Écoute arrêtée.'}async function playCard(c,auto=false){if(!auto){queue=[];automatic=false}active=c.querySelector('audio');if(auto)active.currentTime=0;try{await active.play()}catch(e){automatic=false;queue=[];status.textContent='Cliquez sur le lecteur pour démarrer.'}}cards.forEach(c=>{const a=c.querySelector('audio'),box=c.querySelector('input');const reviewed=tracks.find(t=>t.id===c.dataset.id);if(reviewed.keep===false)box.checked=false;else if(typeof saved[c.dataset.id]==='boolean')box.checked=saved[c.dataset.id];box.onchange=()=>{remember();filter()};a.onplay=()=>{if(!automatic||a!==active){queue=[];automatic=false}active=a;audios.forEach(b=>{if(b!==a)b.pause()});cards.forEach(b=>b.classList.toggle('playing',b===c));const t=tracks.find(t=>t.id===c.dataset.id);status.textContent=t.number+' / '+tracks.length+' · '+t.film+' — '+t.text};a.onended=()=>{if(a!==active)return;c.classList.remove('playing');if(automatic&&queue.length){playCard(queue.shift(),true)}else{automatic=false;status.textContent='Écoute terminée.'}}});document.querySelector('#all').onclick=()=>{stop();queue=cards.filter(c=>!c.hidden);if(!queue.length){status.textContent='Aucun extrait avec ces filtres.';return}automatic=true;const next=queue.shift();next.querySelector('audio').currentTime=0;playCard(next,true)};document.querySelector('#stop').onclick=stop;['film','search','kept'].forEach(id=>document.querySelector('#'+id).oninput=()=>{stop();filter()});document.querySelector('#export').onclick=()=>{remember();const data={sampler:'repliques-cinema-21',choices:tracks.map(t=>({...t,keep:saved[t.id]}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='mes-choix-repliques.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};filter();</script></html>'''
(D/'sampler.html').write_text(page,encoding='utf8')
readme='# Sampler des répliques récemment extraites\n\n21 extraits de six films. Ouvrir sampler.html pour écouter, filtrer et noter les choix. Les deux extraits 3 et 4 de La Chèvre rejetés par l’utilisateur ne sont pas inclus. Aucun fichier audio n’a été retraité ; les empreintes correspondent aux exports individuels.\n\nLa page contient les MP3 pour une écoute autonome. Les dossiers sampler-media/wav et sampler-media/mp3 permettent aussi de télécharger chaque fichier. Exporter mes choix produit mes-choix-repliques.json. La banque du jeu reste inchangée.\n\n'
for r in rows:readme+=f'{r["number"]:02d}. {r["film"]} — {r["text"]} ({r["durationSeconds"]} s)\n\n'
(D/'SAMPLER-README.md').write_text(readme,encoding='utf8')
with zipfile.ZipFile(D/'Repliques-cinema-21-extraits.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
 for r in rows:
  for k in ['wavFile','mp3File']:z.write(D/r[k],r[k])
 for name in ['sampler.html','sampler-manifest.json','sampler-review.json','SAMPLER-README.md']:z.write(D/name,name)
print('Prepared sampler:',len(rows),'clips,',len(films),'films;',round(sum(r['durationSeconds'] for r in rows),2),'seconds; all source hashes preserved.')

